13	// pinned-query API.
14	func drainAudit(t *testing.T, s *Store, org, kind, subject string) []AuditRecord {
15		t.Helper()
16		page, err := s.AuditQuery(org, 1, 4, kind, subject)
17		if err != nil {
18			t.Fatalf("AuditQuery: %v", err)
19		}
20		var out []AuditRecord
21		for {
22			out = append(out, page.Records...)
23			if page.Next == 0 {
24				break
25			}
26			page, err = s.AuditPage(page.Checkpoint, page.Next, 4, kind, subject)
27			if err != nil {
28				t.Fatalf("AuditPage: %v", err)
29			}
30		}
31		return out
32	}
