104	func TestDecideRecordsEveryOutcome(t *testing.T) {
105		s := NewStore()
106		// No published version yet: the denial is still recorded.
107		d0 := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
108		if d0.Allowed || d0.Version != 0 {
109			t.Fatalf("unexpected decision %+v", d0)
110		}
111		if _, err := s.Publish("acme", 0, []Policy{
112			allowPolicy("p-allow", "u1", "read", "org/a", false),
113			{ID: "p-deny", Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectDeny},
114		}); err != nil {
115			t.Fatal(err)
116		}
117		allow := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
118		deny := s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
119		noMatch := s.Decide("acme", request("acme", "u9", "r1", "org/a", "read"))
120		disabled := request("acme", "u1", "r1", "org/a", "read")
121		disabled.Subject.Disabled = true
122		ddis := s.Decide("acme", disabled)
123		mismatch := request("acme", "u1", "r1", "org/a", "read")
124		mismatch.SubjectOrg = "globex"
125		dmis := s.Decide("acme", mismatch)
126		missing := request("acme", "u1", "r1", "org/a", "read")
127		missing.Resource.ID = ""
128		dmiss := s.Decide("acme", missing)
129	
130		recs := drainAudit(t, s, "acme", AuditDecision, "")
131		want := []Decision{d0, allow, deny, noMatch, ddis, dmis, dmiss}
132		if len(recs) != len(want) {
133			t.Fatalf("decision records = %d, want %d", len(recs), len(want))
134		}
135		for i, r := range recs {
136			if r.Kind != AuditDecision || r.Decision == nil {
137				t.Fatalf("record %d not a decision: %+v", i, r)
138			}
139			if !reflect.DeepEqual(r.Decision.Decision, want[i]) {
140				t.Fatalf("record %d decision = %+v, want %+v", i, r.Decision.Decision, want[i])
141			}
142		}
143		// The full request is preserved, including the envelope rejection cases.
144		if recs[4].Decision.Request.Subject.ID != "u1" || !recs[4].Decision.Request.Subject.Disabled {
145			t.Fatalf("disabled request not stored: %+v", recs[4].Decision.Request)
146		}
147		if recs[5].Decision.Request.SubjectOrg != "globex" {
148			t.Fatalf("mismatched org request not stored: %+v", recs[5].Decision.Request)
149		}
150		// Sequences ascend and match the underlying chain positions (the
151		// publish sits at seq 2 and is filtered out of this view).
152		wantSeqs := []int{1, 3, 4, 5, 6, 7, 8}
153		gotSeqs := make([]int, len(recs))
154		for i, r := range recs {
155			gotSeqs[i] = r.Seq
156		}
157		if !reflect.DeepEqual(gotSeqs, wantSeqs) {
158			t.Fatalf("decision seqs = %v, want %v", gotSeqs, wantSeqs)
159		}
160	}
