445		// Modify a field deep inside a payload.
446		check("field change", func(r []AuditRecord) []AuditRecord {
447			r[1].Decision.Decision.Allowed = !r[1].Decision.Decision.Allowed
448			return r
449		}, cp)
450		check("policy change", func(r []AuditRecord) []AuditRecord {
451			r[0].Change.Policies[0].Effect = EffectDeny
452			return r
453		}, cp)
454		// Delete a middle record, keep the tail.
455		check("delete middle", func(r []AuditRecord) []AuditRecord {
456			return []AuditRecord{r[0], r[2], r[3]}
457		}, cp)
458		// Delete the tail while still claiming the original checkpoint.
459		check("delete tail", func(r []AuditRecord) []AuditRecord { return r[:2] }, cp)
460		// A genuine prefix export with its matching checkpoint verifies.
461		prefix, prefixCP, err := s.AuditExport("acme", 2)
462		if err != nil {
463			t.Fatal(err)
464		}
