466			t.Fatalf("prefix export must verify: %v", err)
467		}
468		// Swap order.
469		check("swap order", func(r []AuditRecord) []AuditRecord {
470			r[0], r[1] = r[1], r[0]
471			return r
472		}, cp)
473		// Claim a foreign checkpoint fingerprint.
474		check("foreign checkpoint", func(r []AuditRecord) []AuditRecord { return r },
475			Checkpoint{Org: "acme", EndSeq: 4, Fingerprint: genesisFingerprint("globex")})
476		// Wrong end sequence in the checkpoint.
477		check("wrong length", func(r []AuditRecord) []AuditRecord { return r[:3] }, cp)
