490		if err := VerifyAudit("acme", a, acp); err != nil {
491			t.Fatal(err)
492		}
493		if err := VerifyAudit("globex", g, gcp); err != nil {
494			t.Fatal(err)
495		}
496		// Same sequence numbers, different fingerprints.
497		if a[0].Fingerprint == g[0].Fingerprint || a[1].Fingerprint == g[1].Fingerprint {
498			t.Fatal("organizations share fingerprints despite org-bound genesis")
499		}
500		// A globex record spliced into the acme chain must fail.
501		spliced := append([]AuditRecord(nil), a[0], g[1])
502		if err := VerifyAudit("acme", spliced, Checkpoint{
503			Org: "acme", EndSeq: 2, Fingerprint: spliced[1].Fingerprint,
504		}); err == nil {
505			t.Fatal("foreign-organization record verified in the acme chain")
506		}
507		// Whole globex export cannot verify under the acme name.
508		if err := VerifyAudit("acme", g, gcp); err == nil {
509			t.Fatal("globex export verified as acme")
510		}
511	}
512	
513	func TestRecheckDecisionReplaysRecordedVersion(t *testing.T) {
514		s := NewStore()
515		v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
516		req := request("acme", "u1", "r1", "org/a", "read")
517		original := s.Decide("acme", req) // seq 2, version 1, allowed
518		deniedReq := request("acme", "u2", "r1", "org/a", "read")
519		origDeny := s.Decide("acme", deniedReq) // seq 3, denied by default
520	
521		// Later publish removes the access, then a rollback happens.
522		s.Publish("acme", 1, nil)
523		s.Rollback("acme", 2, 1)
524		// Current version is 3. A fresh decide for u2 would still deny; u1 allowed.
525		// Rechecking seq 2 must reproduce the version-1 allow.
526		got, err := s.RecheckDecision("acme", 2)
527		if err != nil {
528			t.Fatal(err)
529		}
530		if !reflect.DeepEqual(got, original) || got.Version != v1 {
531			t.Fatalf("recheck = %+v, want original %+v (version %d)", got, original, v1)
532		}
533		gotDeny, err := s.RecheckDecision("acme", 3)
534		if err != nil || !reflect.DeepEqual(gotDeny, origDeny) {
535			t.Fatalf("recheck deny = %+v, %v, want %+v", gotDeny, err, origDeny)
536		}
537	
538		// A no-published-version denial rechecks as the same denial.
539		s.Decide("blank", request("blank", "u1", "r1", "org/a", "read"))
540		if d, err := s.RecheckDecision("blank", 1); err != nil || d.Allowed ||
541			d.Reason != "organization has no published version" {
542			t.Fatalf("recheck no-version denial = %+v, %v", d, err)
543		}
544		// An envelope rejection rechecks through the same envelope checks.
545		mismatch := request("acme", "u1", "r1", "org/a", "read")
546		mismatch.SubjectOrg = "globex"
547		s.Decide("acme", mismatch) // publish=seq1, decides=2,3,6; publish=4; rollback=5
548		if d, err := s.RecheckDecision("acme", 6); err != nil || d.Allowed || d.Reason != "organization mismatch" {
549			t.Fatalf("recheck mismatch = %+v, %v", d, err)
550		}
551	
552		// Distinguishable errors.
553		if _, err := s.RecheckDecision("acme", 1); !errors.Is(err, ErrAuditNotADecision) {
554			t.Fatalf("recheck policy_change err = %v", err)
555		}
556		if _, err := s.RecheckDecision("acme", 99); !errors.Is(err, ErrAuditNotFound) {
557			t.Fatalf("recheck missing seq err = %v", err)
558		}
559		if _, err := s.RecheckDecision("ghost", 1); !errors.Is(err, ErrAuditNotFound) {
560			t.Fatalf("recheck unknown org err = %v", err)
561		}
562	}
563	
564	func TestConcurrentOperationsKeepChainConsistent(t *testing.T) {
565		s := NewStore()
566		const publishers = 8
567		const deciders = 8
568		const perDecider = 25
569		var wg sync.WaitGroup
570		var successfulChanges int64
571		var decides int64
572	
573		for i := 0; i < publishers; i++ {
574			wg.Add(1)
575			go func(id int) {
576				defer wg.Done()
577				for j := 0; j < 6; j++ {
578					expected := s.CurrentVersion("acme")
579					pol := []Policy{{
580						ID:      fmt.Sprintf("p-%d-%d", id, j),
581						Subject: fmt.Sprintf("u%d", id),
582						Action:  "read",
583						Scope:   "org/a",
584						Effect:  EffectAllow,
585					}}
586					if v, err := s.Publish("acme", expected, pol); err == nil {
587						atomic.AddInt64(&successfulChanges, 1)
588						_ = v
589						continue
590					}
591					// On conflict, attempt a rollback to a known version.
592					if v, err := s.Rollback("acme", s.CurrentVersion("acme"), 1); err == nil {
593						atomic.AddInt64(&successfulChanges, 1)
594						_ = v
595					}
596				}
597			}(i)
598		}
599		for i := 0; i < deciders; i++ {
600			wg.Add(1)
601			go func(id int) {
602				defer wg.Done()
603				for j := 0; j < perDecider; j++ {
604					s.Decide("acme", request("acme", fmt.Sprintf("u%d", id), "r1", "org/a", "read"))
605					atomic.AddInt64(&decides, 1)
606				}
607			}(i)
608		}
609		wg.Wait()
610	
611		recs, cp, err := s.AuditExport("acme", 0)
612		if err != nil {
613			t.Fatal(err)
614		}
615		// No missing record: one entry per successful change plus every Decide.
616		want := int(successfulChanges) + int(decides)
617		if len(recs) != want {
618			t.Fatalf("records = %d, want %d (changes %d, decides %d)", len(recs), want, successfulChanges, decides)
619		}
620		if err := VerifyAudit("acme", recs, cp); err != nil {
621			t.Fatalf("chain invalid under concurrency: %v", err)
622		}
623		if int64(s.CurrentVersion("acme")) != successfulChanges {
624			t.Fatalf("version %d != successful changes %d", s.CurrentVersion("acme"), successfulChanges)
625		}
626	
627		// No duplicate sequences and every decision matches its recorded version.
628		seen := map[int]bool{}
629		changesAtVersion := map[int]*AuditRecord{}
630		for i := range recs {
631			r := &recs[i]
632			if r.Seq != i+1 {
633				t.Fatalf("gap/dup in sequence at index %d: seq %d", i, r.Seq)
634			}
635			if seen[r.Seq] {
636				t.Fatalf("duplicate sequence %d", r.Seq)
637			}
638			seen[r.Seq] = true
639			if r.Kind == AuditPolicyChange {
640				changesAtVersion[r.Change.Version] = r
641			}
642		}
643		for i := range recs {
644			r := &recs[i]
645			if r.Kind != AuditDecision || r.Decision.Decision.Version == 0 {
646				continue
647			}
648			v := r.Decision.Decision.Version
649			ch, ok := changesAtVersion[v]
650			if !ok {
651				t.Fatalf("decision at seq %d used version %d with no change record", r.Seq, v)
652			}
653			// The decision must be exactly what that version's policies produce.
654			got := evaluate(r.Decision.Request, ch.Change.Policies, v)
655			if !reflect.DeepEqual(got, r.Decision.Decision) {
656				t.Fatalf("seq %d decision %+v does not match version %d evaluation %+v",
657					r.Seq, r.Decision.Decision, v, got)
658			}
659		}
660	}
