204			if err != nil {
205				t.Fatal(err)
206			}
207			if err := VerifyAudit("acme", recs, cp); err != nil {
208				t.Fatalf("mixed-shape policy set must verify: %v", err)
209			}
210			if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
211				t.Fatal("valid-UTF-8 mixed policy set must stay in the JSON fingerprint family")
212			}
213			if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
214				t.Fatalf("mixed-set offline review = %+v, %v", review, err)
215			}
216		})
217	}
218	
219	// TestResourceQualifierDoesNotBypassEnvelopeChecks ensures missing fields,
220	// disabled subjects and organization mismatches reject exactly as before;
221	// naming a resource can never open a back door.
222	func TestResourceQualifierDoesNotBypassEnvelopeChecks(t *testing.T) {
223		s := NewStore()
224		if _, err := s.Publish("acme", 0, []Policy{
225			resourcePolicy("p", "u1", "read", "org/a", "ledger-a", EffectAllow, false),
226		}); err != nil {
227			t.Fatal(err)
228		}
229		base := request("acme", "u1", "ledger-a", "org/a", "read")
230	
231		missingResource := base
232		missingResource.Resource.ID = ""
233		if d := s.Decide("acme", missingResource); d.Allowed || d.Reason != "missing resource id" {
234			t.Fatalf("missing resource id: %+v", d)
235		}
236		disabled := base
237		disabled.Subject.Disabled = true
238		if d := s.Decide("acme", disabled); d.Allowed || d.Reason != "subject is disabled" {
239			t.Fatalf("disabled subject: %+v", d)
240		}
241		mismatch := base
242		mismatch.SubjectOrg = "globex"
243		if d := s.Decide("acme", mismatch); d.Allowed || d.Reason != "organization mismatch" {
244			t.Fatalf("subject org mismatch: %+v", d)
245		}
246		mismatch = base
247		mismatch.ResourceOrg = "globex"
248		if d := s.Decide("acme", mismatch); d.Allowed || d.Reason != "organization mismatch" {
249			t.Fatalf("resource org mismatch: %+v", d)
250		}
251		if d := s.Decide("", base); d.Allowed || d.Reason != "missing decision organization" {
252			t.Fatalf("missing decision org: %+v", d)
253		}
254	}
255	
256	// TestResourceNeedsNoRegistration publishes a resource-qualified policy
257	// without any resource registry and immediately uses it; an empty set with
258	// a later resource policy also keeps working.
259	func TestResourceNeedsNoRegistration(t *testing.T) {
260		s := NewStore()
261		p := resourcePolicy("p", "u1", "read", "org/a", "brand-new-ledger-404", EffectAllow, false)
262		v, err := s.Publish("acme", 0, []Policy{p})
263		if err != nil || v != 1 {
264			t.Fatalf("publish unseen resource policy = %d, %v", v, err)
265		}
266		if d := s.Decide("acme", request("acme", "u1", "brand-new-ledger-404", "org/a", "read")); !d.Allowed {
267			t.Fatalf("unregistered named resource must still match: %+v", d)
268		}
269		// Policies returned from history carry the qualifier in full.
270		got, err := s.Policies("acme", 1)
271		if err != nil || !reflect.DeepEqual(got, []Policy{p}) {
272			t.Fatalf("historical policies = %+v, %v; want %+v", got, err, p)
273		}
274	}
275	
276	// TestResourceQualifierIsVersionedAndRollsBack pins the qualifier to
277	// versions: changing it later never changes review, recheck or offline
278	// recheck of an old decision, and a rollback restores the old qualifier.
279	func TestResourceQualifierIsVersionedAndRollsBack(t *testing.T) {
280		s := NewStore()
281		v1 := 1
282		if v, err := s.Publish("acme", 0, []Policy{
283			resourcePolicy("p", "u1", "read", "org/a", "甲", EffectAllow, false),
284		}); err != nil || v != v1 {
285			t.Fatalf("publish v1 = %d, %v", v, err)
286		}
287		reqA := request("acme", "u1", "甲", "org/a", "read")
288		reqB := request("acme", "u1", "乙", "org/a", "read")
289		originalA := s.Decide("acme", reqA) // seq 2: allowed under v1
290		originalB := s.Decide("acme", reqB) // seq 3: default denial under v1
291		if !originalA.Allowed || originalB.Allowed {
292			t.Fatalf("setup decisions wrong: a=%+v b=%+v", originalA, originalB)
293		}
294	
295		// Move the very same policy from 甲 to 乙.
296		if _, err := s.Publish("acme", v1, []Policy{
297			resourcePolicy("p", "u1", "read", "org/a", "乙", EffectAllow, false),
298		}); err != nil {
299			t.Fatal(err)
300		}
301		// Current version flips the outcomes.
302		if d := s.Decide("acme", reqA); d.Allowed {
303			t.Fatalf("v2 must no longer allow 甲: %+v", d)
304		}
305		if d := s.Decide("acme", reqB); !d.Allowed {
306			t.Fatalf("v2 must now allow 乙: %+v", d)
307		}
308		// Historical review stays pinned to v1.
309		if d := s.Review("acme", v1, reqA); !reflect.DeepEqual(d, originalA) {
310			t.Fatalf("v1 review changed: %+v want %+v", d, originalA)
311		}
312		if d := s.Review("acme", v1, reqB); !reflect.DeepEqual(d, originalB) {
313			t.Fatalf("v1 review of 乙 changed: %+v want %+v", d, originalB)
314		}
315		// Online recheck of the recorded v1 decisions is unchanged.
316		if d, err := s.RecheckDecision("acme", 2); err != nil || !reflect.DeepEqual(d, originalA) {
317			t.Fatalf("recheck seq2 = %+v, %v; want %+v", d, err, originalA)
318		}
319		if d, err := s.RecheckDecision("acme", 3); err != nil || !reflect.DeepEqual(d, originalB) {
320			t.Fatalf("recheck seq3 = %+v, %v; want %+v", d, err, originalB)
321		}
322	
323		// Offline recheck from an export ending at v2 reproduces the v1 verdicts.
324		recs, cp, err := s.AuditExport("acme", 0)
325		if err != nil {
326			t.Fatal(err)
327		}
328		for _, seq := range []int{2, 3} {
329			review, err := RecheckDecisionOffline("acme", recs, cp, seq)
330			if err != nil {
331				t.Fatalf("offline recheck seq %d: %v", seq, err)
332			}
333			if !review.Consistent {
334				t.Fatalf("offline recheck seq %d inconsistent: %+v vs %+v", seq, review.Original, review.Recomputed)
335			}
336		}
337	
338		// A rollback restores the 甲 qualifier as a new version and records it.
339		v3, err := s.Rollback("acme", 2, v1)
340		if err != nil || v3 != 3 {
341			t.Fatalf("rollback = %d, %v", v3, err)
342		}
343		if d := s.Decide("acme", reqA); !d.Allowed || d.Version != 3 {
344			t.Fatalf("after rollback 甲 must be allowed under v3: %+v", d)
345		}
346		rolled, err := s.Policies("acme", 3)
347		if err != nil {
348			t.Fatal(err)
349		}
350		if rolled[0].ResourceID != "甲" {
351			t.Fatalf("rolled back qualifier = %q, want 甲", rolled[0].ResourceID)
352		}
353	}
354	
355	// TestResourceQualifierTamperingBreaksChain proves the qualifier is part of
356	// the signed policy content: changing it in exported material while keeping
357	// the original fingerprints and checkpoint must fail verification online and
358	// block offline review.
359	func TestResourceQualifierTamperingBreaksChain(t *testing.T) {
360		s := NewStore()
361		p := resourcePolicy("p", "u1", "read", "org/a", "ledger-a", EffectAllow, false)
362		s.Publish("acme", 0, []Policy{p})
363		s.Decide("acme", request("acme", "u1", "ledger-a", "org/a", "read"))
364	
365		good, cp, err := s.AuditExport("acme", 0)
366		if err != nil {
367			t.Fatal(err)
368		}
369		tampered := cloneExportedRecords(good)
370		tampered[0].Change.Policies[0].ResourceID = "ledger-b"
371		if err := VerifyAudit("acme", tampered, cp); !errors.Is(err, ErrInvalidRange) {
372			t.Fatalf("changed qualifier err = %v, want ErrInvalidRange", err)
373		}
374		if _, err := RecheckDecisionOffline("acme", tampered, cp, 2); !errors.Is(err, ErrInvalidRange) {
375			t.Fatalf("offline review over tampered qualifier err = %v", err)
376		}
377	
378		// Adding a qualifier to an originally unrestricted policy is content
379		// change too, even though its fingerprints otherwise stay legacy.
380		s2 := NewStore()
381		s2.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
382		s2.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
383		plain, plainCP, err := s2.AuditExport("acme", 0)
384		if err != nil {
385			t.Fatal(err)
386		}
387		if fingerprintFor(&plain[0]) != legacyJSONFingerprint(&plain[0]) {
388			t.Fatal("unrestricted policy must keep the legacy fingerprint")
389		}
390		added := cloneExportedRecords(plain)
391		added[0].Change.Policies[0].ResourceID = "ledger-a"
392		if err := VerifyAudit("acme", added, plainCP); !errors.Is(err, ErrInvalidRange) {
393			t.Fatalf("newly added qualifier err = %v, want ErrInvalidRange", err)
394		}
395	}
396	
397	// TestResourceQualifierFingerprints shows valid-UTF-8 qualified policies
398	// extend the legacy JSON fingerprint family (so the two encodings agree),
399	// while invalid bytes in ResourceID take the raw path and remain
400	// distinguishable after export and offline review.
401	func TestResourceQualifierFingerprints(t *testing.T) {
402		org := "acme"
403		p := resourcePolicy("p1", "u1", "read", "org/a", "ledger-中", EffectAllow, false)
404		prev := genesisFingerprint(org)
405		rec := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
406			Version: 1, Policies: []Policy{p},
407		}, nil, prev)
408		if fingerprintFor(&rec) != legacyJSONFingerprint(&rec) {
409			t.Fatal("valid-UTF-8 resource qualifier must stay in the JSON fingerprint family")
410		}
411		// Sanity: a JSON fingerprint genuinely covers the qualifier.
412		changedRecs := cloneExportedRecords([]AuditRecord{rec})
413		changedRecs[0].Change.Policies[0].ResourceID = "ledger-文"
414		if fingerprintFor(&changedRecs[0]) == fingerprintFor(&rec) {
415			t.Fatal("changing the qualifier did not change the JSON fingerprint")
416		}
417	
418		// Invalid UTF-8 in the qualifier is accepted, preserved byte for byte,
419		// and hashed through the raw encoding.
420		s := NewStore()
421		raw := resourcePolicy("p", "u1", "read", "org/a", "账"+invalidByte+"本", EffectAllow, false)
422		if _, err := s.Publish(org, 0, []Policy{raw}); err != nil {
423			t.Fatal(err)
424		}
425		if d := s.Decide(org, request(org, "u1", "账"+invalidByte+"本", "org/a", "read")); !d.Allowed {
426			t.Fatalf("raw-byte resource must match raw-byte qualifier: %+v", d)
427		}
428		// The display-identical genuine U+FFFD rune is a different resource and
429		// must not match.
430		if d := s.Decide(org, request(org, "u1", "账"+replacementRune+"本", "org/a", "read")); d.Allowed {
431			t.Fatalf("replacement-rune resource must not match raw-byte qualifier: %+v", d)
432		}
433		recs, cp, err := s.AuditExport(org, 0)
434		if err != nil {
435			t.Fatal(err)
436		}
437		if err := VerifyAudit(org, recs, cp); err != nil {
438			t.Fatalf("raw-byte qualifier chain must verify: %v", err)
439		}
440		exported := recs[0].Change.Policies[0]
441		if !reflect.DeepEqual(exported, raw) || !strings.Contains(exported.ResourceID, invalidByte) {
442			t.Fatalf("qualifier bytes not preserved: %+v want %+v", exported, raw)
443		}
444		if fingerprintFor(&recs[0]) == legacyJSONFingerprint(&recs[0]) {
445			t.Fatal("raw-byte qualifier must leave the JSON fingerprint family")
446		}
447	
448		// Substituting the lone invalid byte for 0xFE or a real U+FFFD while
449		// keeping the fingerprint and checkpoint must fail.
450		for _, repl := range []string{anotherInvalidByte, replacementRune} {
451			bad := cloneExportedRecords(recs)
452			bad[0].Change.Policies[0].ResourceID = strings.Replace(bad[0].Change.Policies[0].ResourceID, invalidByte, repl, 1)
453			if err := VerifyAudit(org, bad, cp); !errors.Is(err, ErrInvalidRange) {
454				t.Fatalf("qualifier repl=%s err = %v, want ErrInvalidRange", replacementLabel(repl), err)
455			}
456		}
457	
458		// Offline review of the recorded raw-byte-named resource decision at
459		// seq 2 reproduces the allow byte for byte.
460		review, err := RecheckDecisionOffline(org, recs, cp, 2)
461		if err != nil || !review.Consistent || !review.Recomputed.Allowed {
462			t.Fatalf("offline raw-byte review = %+v, %v", review, err)
463		}
464	}
